import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join, normalize, relative } from "node:path";
import type { CheckResult } from "../../../types/index.js";
import { AUTOGENERATED_DIR, PACKAGE_JSON } from "../../constants.js";
import { formatCount } from "../../formatting.js";
import { findProjectRoot } from "../../paths.js";
import { discoverResourcesFromRoot } from "../../services.js";

/**
 * `.autogenerated/` is written by `flisk up`, so a resource without it has simply not been generated yet.
 * That is a warning, not a failure: `flisk doctor` is also run before the first `flisk up`.
 */
/** Regular files under `.autogenerated/`, nested ones included, without the `.flisk-contract` bookkeeping directory. */
function listGeneratedFiles(root: string): string[] {
  const files: string[] = [];
  const collect = (dir: string, relativeDir: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (relativeDir === "" && entry.name === ".flisk-contract") continue;
      const relativeFile = relativeDir === "" ? entry.name : `${relativeDir}/${entry.name}`;
      if (entry.isDirectory()) collect(join(dir, entry.name), relativeFile);
      else if (entry.isFile()) files.push(relativeFile);
    }
  };
  collect(root, "");
  return files.sort((a, b) => a.localeCompare(b));
}

export function checkGeneratedFiles(strict = false): CheckResult {
  const projectRoot = findProjectRoot() ?? process.cwd();
  const resources = discoverResourcesFromRoot(projectRoot).filter(
    (resource) => (resource.config?.appType ?? resource.type) !== "library",
  );

  if (resources.length === 0) {
    return {
      name: "Generated Files",
      didPass: true,
      isSkipped: true,
      message: "No resources to check",
    };
  }

  const lines: string[] = [];
  const missing: string[] = [];
  for (const resource of resources) {
    const label = normalize(relative(projectRoot, resource.path));
    const dir = join(resource.path, AUTOGENERATED_DIR);
    const files = existsSync(dir) ? listGeneratedFiles(dir) : [];
    if (files.length === 0) {
      missing.push(label);
      lines.push(`${label}: no ${AUTOGENERATED_DIR}/ files`);
    } else {
      lines.push(`${label}: ${files.join(", ")}`);
    }
  }

  if (missing.length === 0) {
    return {
      name: "Generated Files",
      didPass: true,
      message: `${formatCount(resources.length, "resource")} with generated files:\n    ${lines.join("\n    ")}`,
    };
  }

  return {
    name: "Generated Files",
    didPass: false,
    isWarning: !strict,
    message: `${missing.length} of ${formatCount(resources.length, "resource")} not generated yet:\n    ${lines.join("\n    ")}`,
    fix: "Run `flisk up` to generate them (it needs Docker, Compose and Tilt). `flisk config verify` checks the project-level files only.",
  };
}

// Only docker-templates files that a generated Dockerfile actually copies are
// required. A fresh starter has no generated Dockerfiles, so it must not fail
// for templates it never references (#4583).
const TEMPLATE_SOURCE_PATTERN =
  /^(?:\.\/)?shared-platform-engineering\/docker-templates\/([\w.-]+)$/;

function parseEscapeChar(lines: string[]): string {
  for (const raw of lines) {
    const trimmed = raw.trim();
    // Docker no longer looks for parser directives once a blank line, a builder instruction, or an ordinary comment
    // has been processed (https://docs.docker.com/reference/dockerfile/#parser-directives). Only other directive lines
    // (`# key=value`, such as `# syntax=`) may precede `# escape=`.
    if (trimmed === "") return "\\";
    const directive = /^#\s*escape\s*=\s*([\\`])\s*$/i.exec(trimmed);
    if (directive?.[1]) return directive[1];
    if (!DIRECTIVE_LINE_PATTERN.test(trimmed)) return "\\";
  }
  return "\\";
}

// A directive line names a directive: `# <key>=<value>`. Anything else starting with `#` is an ordinary comment.
const DIRECTIVE_LINE_PATTERN = /^#\s*[A-Za-z][\w-]*\s*=/;

// `<<EOF`, `<<-EOF`, `<<"EOF"` and `<<'EOF'` start a heredoc whose body is data of the enclosing instruction.
const HEREDOC_PATTERN = /<<(-?)(?:"([^"]+)"|'([^']+)'|([^\s<>"'|&;()]+))/g;

function heredocDelimiters(instruction: string): { word: string; stripTabs: boolean }[] {
  const delimiters: { word: string; stripTabs: boolean }[] = [];
  for (const match of instruction.matchAll(HEREDOC_PATTERN)) {
    const word = match[2] ?? match[3] ?? match[4];
    if (word) delimiters.push({ word, stripTabs: match[1] === "-" });
  }
  return delimiters;
}

function collectDockerfileInstructions(content: string): string[] {
  const rawLines = content.split(/\r?\n/);
  const escapeChar = parseEscapeChar(rawLines);
  const instructions: string[] = [];
  let current = "";
  let pendingHeredocs: { word: string; stripTabs: boolean }[] = [];
  const continuation = new RegExp(`${escapeChar === "`" ? "`" : "\\\\"}[ \\t]*$`);

  for (const rawLine of rawLines) {
    if (pendingHeredocs.length > 0) {
      // Heredoc bodies belong to the instruction that opened them; skip them up to each delimiter line.
      const [heredoc] = pendingHeredocs;
      const candidate = heredoc?.stripTabs ? rawLine.replace(/^\t+/, "") : rawLine;
      if (candidate === heredoc?.word) pendingHeredocs.shift();
      continue;
    }

    // Docker trims leading whitespace of every line, including continuation lines.
    const line = rawLine.trimStart();
    if (line.trim() === "" || line.startsWith("#")) {
      // Blank and comment lines are ignored both between instructions and inside continuations.
      continue;
    }

    // The escape character may be followed by trailing whitespace. Docker removes it and joins the lines with no
    // separator, so whitespace before the escape character stays and a path split across lines is rejoined.
    const continued = continuation.test(line);
    const segment = continued ? line.replace(continuation, "") : line.trimEnd();
    current += segment;

    if (!continued) {
      instructions.push(current);
      pendingHeredocs = heredocDelimiters(current);
      current = "";
    }
  }
  if (current) {
    instructions.push(current);
  }
  return instructions;
}

function splitShellTokens(input: string): string[] {
  const tokens: string[] = [];
  let current = "";
  let quote: '"' | "'" | null = null;
  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    if (quote) {
      if (ch === quote) {
        quote = null;
      } else {
        current += ch;
      }
    } else if (ch === '"' || ch === "'") {
      quote = ch;
    } else if (/\s/.test(ch)) {
      if (current.length > 0) {
        tokens.push(current);
        current = "";
      }
    } else {
      current += ch;
    }
  }
  if (current.length > 0) {
    tokens.push(current);
  }
  return tokens;
}

function extractCopySources(instruction: string): string[] {
  const match = /^COPY\s+(\S.*)$/i.exec(instruction);
  if (!match?.[1]) return [];

  let rest = match[1].trimStart();
  while (rest.startsWith("--")) {
    const flagMatch = /^(--\S+)\s+(\S[\s\S]*)$/.exec(rest);
    if (!flagMatch?.[1] || !flagMatch[2]) return [];
    // `COPY --from=<stage|image>` reads from another stage or image, not the host build context.
    if (/^--from=/i.test(flagMatch[1])) return [];
    rest = flagMatch[2].trimStart();
  }

  if (rest.startsWith("[")) {
    try {
      const parsed: unknown = JSON.parse(rest);
      if (
        Array.isArray(parsed) &&
        parsed.length >= 2 &&
        parsed.every((item): item is string => typeof item === "string")
      ) {
        return parsed.slice(0, -1);
      }
    } catch {
      return [];
    }
    return [];
  }

  const tokens = splitShellTokens(rest);
  return tokens.length >= 2 ? tokens.slice(0, -1) : [];
}

function extractCopiedTemplateFiles(dockerfileContent: string): string[] {
  const referenced = new Set<string>();
  for (const instruction of collectDockerfileInstructions(dockerfileContent)) {
    for (const source of extractCopySources(instruction)) {
      const normalizedSource = source.replace(/\\/g, "/").replace(/^\/+/, "");
      const match = TEMPLATE_SOURCE_PATTERN.exec(normalizedSource);
      if (match?.[1] && match[1] !== "." && match[1] !== "..") {
        referenced.add(match[1]);
      }
    }
  }
  return [...referenced];
}

interface TemplateScanResult {
  referenced: string[];
  scanErrors: string[];
}

/** docker-templates files named in COPY instructions of generated Dockerfiles. */
function findReferencedTemplateFiles(projectRoot: string): TemplateScanResult {
  const referenced = new Set<string>();
  const scanErrors: string[] = [];

  // The golden layers Dockerfile copies install-deps.sh and prisma-bun-client-link-fix.sh; resources never see it.
  const goldenDockerfile = join(projectRoot, ".flisk", ".flisk-out", "golden-layers.Dockerfile");
  if (existsSync(goldenDockerfile)) {
    try {
      for (const file of extractCopiedTemplateFiles(readFileSync(goldenDockerfile, "utf-8"))) {
        referenced.add(file);
      }
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      scanErrors.push(`${normalize(relative(projectRoot, goldenDockerfile))}: ${detail}`);
    }
  }

  let resources: ReturnType<typeof discoverResourcesFromRoot>;
  try {
    resources = discoverResourcesFromRoot(projectRoot);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    return {
      referenced: [],
      scanErrors: [`failed to discover resources: ${detail}`],
    };
  }

  for (const resource of resources) {
    const dir = join(resource.path, AUTOGENERATED_DIR);
    if (!existsSync(dir)) continue;

    let entries: string[];
    try {
      entries = readdirSync(dir);
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      scanErrors.push(`${normalize(relative(projectRoot, dir))}: ${detail}`);
      continue;
    }

    for (const entry of entries) {
      if (!entry.startsWith("Dockerfile") || entry.endsWith(".dockerignore")) continue;
      const filePath = join(dir, entry);
      let content: string;
      try {
        content = readFileSync(filePath, "utf-8");
      } catch (error) {
        const detail = error instanceof Error ? error.message : String(error);
        scanErrors.push(`${normalize(relative(projectRoot, filePath))}: ${detail}`);
        continue;
      }
      for (const file of extractCopiedTemplateFiles(content)) {
        referenced.add(file);
      }
    }
  }

  return { referenced: [...referenced], scanErrors };
}

export function checkGeneratedProjectRuntimeAssets(): CheckResult {
  const projectRoot = findProjectRoot() ?? process.cwd();
  const missing: string[] = [];
  const crlf: string[] = [];

  if (!existsSync(join(projectRoot, PACKAGE_JSON))) {
    missing.push(`${PACKAGE_JSON} (workspace root manifest)`);
  }

  const templateDir = join(projectRoot, "shared-platform-engineering", "docker-templates");
  const { referenced, scanErrors } = findReferencedTemplateFiles(projectRoot);
  for (const file of referenced) {
    const relative = `shared-platform-engineering/docker-templates/${file}`;
    const filePath = join(templateDir, file);
    if (!existsSync(filePath)) {
      missing.push(relative);
      continue;
    }
    // A CR on the shebang line is enough to break every Linux image build, so
    // catch it here instead of letting `flisk up` fail minutes later.
    const firstLine = readFileSync(filePath, "utf-8").split("\n", 1)[0] ?? "";
    if (firstLine.includes("\r")) {
      crlf.push(relative);
    }
  }

  const problems = [
    ...missing.map((file) => `missing: ${file}`),
    ...crlf.map((file) => `CRLF first line: ${file}`),
  ];
  if (problems.length === 0 && scanErrors.length === 0) {
    return {
      name: "Generated Runtime Assets",
      didPass: true,
      message: "Generated Docker runtime assets are present",
    };
  }

  if (problems.length === 0) {
    return {
      name: "Generated Runtime Assets",
      didPass: false,
      message: `Failed to inspect generated Dockerfiles for runtime assets:\n    ${scanErrors.join("\n    ")}`,
      fix: "Check file permissions or regenerate the affected `.autogenerated/` files with `flisk config regenerate`, then re-run `flisk doctor`.",
    };
  }

  const details = [...problems, ...scanErrors.map((err) => `scan error (${err})`)];
  return {
    name: "Generated Runtime Assets",
    didPass: false,
    message: `Generated Docker runtime assets have problems:\n    ${details.join("\n    ")}`,
    fix:
      crlf.length > 0
        ? "Line endings: run flisk config regenerate to rewrite CRLF scripts with LF"
        : "Run `flisk project --yes` (or `flisk config regenerate`) with an updated Flisk. `flisk up` also refreshes these assets before starting Tilt.",
  };
}
